#  SES (TTS) AYARI — Kadın / Erkek
SES_AYAR_DOSYASI = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ses_ayari.json")
_ses_cinsiyeti = "kadin"

def _ses_ayarini_yukle():
    global _ses_cinsiyeti
    data = JsonStateStore(SES_AYAR_DOSYASI).load()
    if data.get("cinsiyet") in ("kadin", "erkek"):
        _ses_cinsiyeti = data["cinsiyet"]

def ses_cinsiyeti_getir():
    return _ses_cinsiyeti

def ses_cinsiyeti_ayarla(cinsiyet):
    global _ses_cinsiyeti
    if cinsiyet not in ("kadin", "erkek"):
        return False
    try:
        JsonStateStore(SES_AYAR_DOSYASI).save({"cinsiyet": cinsiyet})
    except (OSError, TypeError, ValueError) as exc:
        print(f"[UYARI] Ses ayarı kaydedilemedi: {type(exc).__name__}")
        return False
    _ses_cinsiyeti = cinsiyet
    print(f"[OK] Ses cinsiyeti ayarlandı: {cinsiyet}")
    return True

_ses_ayarini_yukle()

# ==============================================================================
# ANKA.PNG DOSYASINI BASE64'E ÇEVİR
# ==============================================================================
# anka.png dosyanın TAMAMI (kırpılmadan, küçültülmeden) doğrudan koda gömüldü.
# Böylece dosya yolu / çalışma dizini farkı yüzünden resim kaybolmaz.
ANKA_IMG_BASE64_EMBEDDED = ""

ANKA_IMG_BASE64 = ANKA_IMG_BASE64_EMBEDDED

def load_anka_image():
    """Eğer proje klasöründe ayrı bir anka.png varsa onu kullanmayı dener
    (ör. logo güncellemek için); bulunamazsa koda gömülü olan görsel kullanılır."""
    global ANKA_IMG_BASE64
    possible_paths = [
        "anka.png",
        "./anka.png",
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "anka.png"),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "images", "anka.png")
    ]
    for path in possible_paths:
        if os.path.exists(path):
            try:
                with open(path, "rb") as f:
                    data = f.read()
                    ANKA_IMG_BASE64 = base64.b64encode(data).decode("utf-8")
                    print(f"[OK] anka.png disktan yüklendi: {path} ({len(data)} bayt)")
                    return
            except Exception as e:
                print(f"[HATA] anka.png okunamadı, gömülü görsel kullanılacak: {e}")
                return
    print("[OK] Diskte anka.png bulunamadı, koda gömülü ANKA AI görseli kullanılıyor.")

load_anka_image()

