    def dosya_ogret_sec(self):
        """'📎 PDF / Word / TXT Seç' butonuna basılınca çalışır: yerel dosya
        seçme penceresi açar, seçilen dosyayı arka planda okuyup parçalara
        böler ve veritabanına kaydeder. Sonrasında bu dosyayla ilgili sorular
        sorulabilir (bkz. dosya_ogretici.dosya_sorusu_cevapla); bilinmeyen
        sorularda asistan otomatik olarak internete başvurur (web_bilgi.py)."""
        global _asis
        try:
            if _asis is None:
                self._ogret_durum("⚠️ Asistan bağlantısı kurulamadı.")
                return
            _asis.permissions.check(Permission.FILES)
            if not webview.windows:
                return
            secilenler = webview.windows[0].create_file_dialog(
                webview.OPEN_DIALOG,
                allow_multiple=False,
                file_types=("Desteklenen dosyalar (*.pdf;*.docx;*.txt)",)
            )
            if not secilenler:
                return
            dosya_yolu = secilenler[0]
            dosya_adi = dosya_yolu.replace("\\", "/").split("/")[-1]

            cursor = getattr(_asis, "cursor", None)
            conn = getattr(_asis, "conn", None)
            if cursor is None or conn is None:
                self._ogret_durum("⚠️ Veritabanı bağlantısı bulunamadı.")
                return

            self._ogret_durum(f"⏳ '{dosya_adi}' öğreniliyor, lütfen bekleyin...")

            def arka_planda_ogret():
                import dosya_ogretici
                try:
                    guvenli_yol = resolve_user_file(dosya_yolu)
                    source_name, content = DocumentLearner().read(str(guvenli_yol))
                    _asis.memory_store.remember(
                        "knowledge", content[:8000], {"source": source_name, "kind": "document"}
                    )
                    basarili, mesaj = dosya_ogretici.dosyadan_ogren(cursor, conn, str(guvenli_yol))
                except (FileProcessingError, PermissionDeniedError) as exc:
                    basarili, mesaj = False, f"Dosya güvenlik kontrolünden geçemedi: {exc}"
                except (OSError, ValueError, sqlite3.Error) as exc:
                    basarili, mesaj = False, "Dosya öğretilirken güvenli biçimde tamamlanamayan bir hata oluştu."
                    print(f"[HATA] Dosya öğretme işlemi başarısız: {exc}")
                self._ogret_durum(("✅ " if basarili else "❌ ") + mesaj)
                self._ogretilmis_dosyalari_yenile()

            threading.Thread(target=arka_planda_ogret, daemon=True).start()
        except (OSError, RuntimeError, TypeError, ValueError, sqlite3.Error) as error:
            print(f"[HATA] Dosya öğretme hatası: {type(error).__name__}")
            self._ogret_durum("❌ Dosya öğretilirken hata oluştu. Dosyayı ve izinleri kontrol edin.")

    def _ogret_durum(self, text):
        try:
            if webview.windows:
                safe = json.dumps(str(text), ensure_ascii=False)
                webview.windows[0].evaluate_js(f"ogretmeDurumGuncelle({safe})")
        except Exception as e:
            print(f"[HATA] Öğretme durumu güncellenemedi: {e}")

    def _ogretilmis_dosyalari_yenile(self):
        try:
            if webview.windows:
                webview.windows[0].evaluate_js("refreshOgretilmisDosyalar()")
        except Exception as e:
            print(f"[HATA] Dosya listesi yenilenemedi: {e}")

    def ogretilen_dosyalari_getir(self):
        """Öğrenilmiş (dosya_parcalari tablosundaki) dosya adlarının
        listesini döndürür - 'Dosya Öğret' sekmesindeki liste için."""
        global _asis
        try:
            cursor = getattr(_asis, "cursor", None) if _asis else None
            if cursor is None:
                return []
            cursor.execute("SELECT DISTINCT dosya_adi FROM dosya_parcalari ORDER BY dosya_adi")
            return [row[0] for row in cursor.fetchall()]
        except Exception as e:
            print(f"[HATA] Dosya listesi alınamadı: {e}")
            return []

