def sistem_bilgisi_guncelle():
    try:
        cpu = psutil.cpu_percent(interval=0.5)
        ram = psutil.virtual_memory()
        disk = psutil.disk_usage('/')
        bat = psutil.sensors_battery()
        bat_percent = bat.percent if bat else 0

        if webview.windows:
            js = f"""
                document.getElementById('sys-cpu').textContent = '{cpu}%';
                document.getElementById('sys-cpu-bar').style.width = '{cpu}%';
                document.getElementById('sys-ram').textContent = '{round(ram.used / (1024**3), 1)} / {round(ram.total / (1024**3), 1)} GB';
                document.getElementById('sys-ram-bar').style.width = '{ram.percent}%';
                document.getElementById('sys-disk').textContent = '{disk.percent}%';
                document.getElementById('sys-disk-bar').style.width = '{disk.percent}%';
                document.getElementById('sys-bat').textContent = '{bat_percent}%';
                document.getElementById('sys-bat-bar').style.width = '{bat_percent}%';
                document.getElementById('trai-cpu').textContent = '{cpu}%';
                document.getElementById('trai-ram').textContent = '{ram.percent}%';
                document.getElementById('trai-disk').textContent = '{disk.percent}%';
                document.getElementById('trai-bat').textContent = '{bat_percent}%';
                const battery = document.getElementById('status-battery');
                if (battery) battery.textContent = '⚡{bat_percent}%';
            """
            webview.windows[0].evaluate_js(js)
    except Exception as e:
        print(f"Sistem bilgisi güncelleme hatası: {e}")

