def kripto_guncelle(btc: str, eth: str, sol: str, btc_chg: str, eth_chg: str, sol_chg: str):
    try:
        if webview.windows:
            values = json.dumps(
                {
                    "btc": str(btc), "eth": str(eth), "sol": str(sol),
                    "btc_chg": str(btc_chg), "eth_chg": str(eth_chg), "sol_chg": str(sol_chg),
                },
                ensure_ascii=False,
            )
            js = f"""
                const values = {values};
                var btc_e = document.querySelector('.crypto-item:nth-child(1) .crypto-usd');
                if(btc_e) btc_e.textContent = values.btc;
                var btc_c = document.querySelector('.crypto-item:nth-child(1) .crypto-chg');
                if(btc_c) {{ btc_c.textContent = values.btc_chg; btc_c.className = 'crypto-chg ' + (values.btc_chg.startsWith('+') ? 'up' : 'dn'); }}
                var home_btc = document.getElementById('home-btc');
                if(home_btc) home_btc.textContent = values.btc;
                var home_btc_c = document.getElementById('home-btc-chg');
                if(home_btc_c) {{ home_btc_c.textContent = values.btc_chg; home_btc_c.className = home_btc_c.className.replace(/\\b(up|dn)\\b/g, '') + (values.btc_chg.startsWith('+') ? ' up' : ' dn'); }}
                var eth_e = document.querySelector('.crypto-item:nth-child(2) .crypto-usd');
                if(eth_e) eth_e.textContent = values.eth;
                var eth_c = document.querySelector('.crypto-item:nth-child(2) .crypto-chg');
                if(eth_c) {{ eth_c.textContent = values.eth_chg; eth_c.className = 'crypto-chg ' + (values.eth_chg.startsWith('+') ? 'up' : 'dn'); }}
                var sol_e = document.querySelector('.crypto-item:nth-child(3) .crypto-usd');
                if(sol_e) sol_e.textContent = values.sol;
                var sol_c = document.querySelector('.crypto-item:nth-child(3) .crypto-chg');
                if(sol_c) {{ sol_c.textContent = values.sol_chg; sol_c.className = 'crypto-chg ' + (values.sol_chg.startsWith('+') ? 'up' : 'dn'); }}
            """
            webview.windows[0].evaluate_js(js)
    except Exception as e:
        print(f"[HATA] Kripto güncellenemedi: {e}")

