def arayuz_baslat(pencere_basligi: str = "Anka", asistan=None, groq=None):
    if asistan is not None:
        set_asistan(asistan)
    if groq is not None:
        set_groq(groq)

    # ANKA_IMG_BASE64 değişimi artık modül yüklenirken DIJIDOST_HTML'in
    # kendi içine gömülüyor (yukarıya bakınız), bu yüzden burada tekrar
    # replace yapmaya gerek yok; DIJIDOST_HTML zaten hazır.
    html_content = DIJIDOST_HTML

    import tempfile
    temp_html = tempfile.NamedTemporaryFile(delete=False, suffix=".html", mode="w", encoding="utf-8")
    temp_html.write(html_content)
    temp_html.close()
    html_path = temp_html.name

    api_obj = API()

    window = webview.create_window(
        pencere_basligi,
        html_path,
        width=1600,
        height=900,
        min_size=(420, 700),
        resizable=True,
        background_color='#0d0202',
        js_api=api_obj
    )

    def _sistem_guncelle():
        while True:
            try:
                sistem_bilgisi_guncelle()
                batarya_guncelle()
            except Exception as e:
                print(f"Sistem güncelleme hatası: {e}")
            time.sleep(5)
    threading.Thread(target=_sistem_guncelle, daemon=True).start()

    webview.start(debug=False)

if __name__ == "__main__":
    print("=" * 60)
    print("  Anka — Modern Youth Interface")
    print("=" * 60)
    arayuz_baslat()
